insert into photo_jobs (kind, params) values ('edition', $job${"id":"art-ed-dw-umber-1","style":"dark-walnut","prompt":"Abstract painting in ink and thinned oil on raw linen canvas. Colours: warm white ground, oat, deep umber, a little warm black ink, one small rust accent. Composition: one broad sweeping umber wash rising from the lower left and crossing to the upper right, thinning into translucent veils; a soft ink dry-brush edge along its lower side; a single small rust mark in the right third; about two thirds of the surface stays light, calm and open. Texture: visible linen weave, layered translucent glazes, soft bleeding edges, a few dry-brush drags. One image, hung as two panels: keep the centre band and the edges free of key marks. The artwork alone, flat and frontal, edge to edge: no frame, no wall, no perspective, no text, no signature.","palette":["#B5674A","#ECE7DE","#D3C6B1","#553C2C","#1F1E1C"],"aspect":"3:2","candidates":2,"resolution":"2K"}$job$::jsonb);
insert into photo_jobs (kind, params) values ('edition', $job${"id":"art-ed-dw-ink-field","style":"dark-walnut","prompt":"Tonal abstract painting, ink wash and oil glaze on canvas. Colours: warm white, oat, umber, warm black ink, one thin rust line. Composition: a wide, horizon-less field; pale oat haze across the upper two thirds settling into a deep umber and ink band low in the picture, heavier toward the right; one thin horizontal rust line just above the dark band, broken in two places; no objects, no landscape features. Texture: layered washes with tide marks, pooled pigment, fine canvas weave showing through the thin areas. Keep key marks off the edges. The artwork alone, flat and frontal, edge to edge: no frame, no wall, no perspective, no text, no signature.","palette":["#B5674A","#ECE7DE","#D3C6B1","#553C2C","#1F1E1C"],"aspect":"3:2","candidates":2,"resolution":"2K"}$job$::jsonb);
insert into photo_jobs (kind, params) values ('edition', $job${"id":"art-ed-dw-umber-2","style":"dark-walnut","prompt":"Quiet abstract painting in thinned oil and ink on linen. Colours: warm white ground, oat, umber, a trace of rust. Composition: two soft rounded umber forms of unequal size leaning toward each other slightly left of centre, their edges dissolving into the ground; a pale oat veil behind them; a hair-thin rust arc where they almost touch; at least three quarters of the surface is light and empty. Texture: soft matte glazes, feathered edges, linen weave, no hard lines. Keep key marks off the edges. The artwork alone, flat and frontal, edge to edge: no frame, no wall, no perspective, no text, no signature.","palette":["#B5674A","#ECE7DE","#D3C6B1","#553C2C"],"aspect":"4:3","candidates":2,"resolution":"2K"}$job$::jsonb);
insert into photo_jobs (kind, params) values ('edition', $job${"id":"art-ed-dw-warm-shadow","style":"dark-walnut","prompt":"Tonal abstract painting, oil glaze over a plaster-like ground on canvas. Colours: warm white, oat, umber, a faint rust glow. Composition: a soft diagonal gradient like late-afternoon shadow falling across a plaster wall, from light upper left to a warm umber shadow in the lower right corner; a faint rust warmth along the edge of the shadow; no shapes, no objects. Texture: chalky matte surface, broad soft brush drags, subtle trowel marks under the glaze. Keep key marks off the edges. The artwork alone, flat and frontal, edge to edge: no frame, no wall, no perspective, no text, no signature.","palette":["#B5674A","#ECE7DE","#D3C6B1","#553C2C"],"aspect":"4:3","candidates":2,"resolution":"2K"}$job$::jsonb);
insert into photo_jobs (kind, params) values ('edition', $job${"id":"art-ed-dw-rust-stroke","style":"dark-walnut","prompt":"Abstract ink painting on heavy cotton paper mounted on canvas, vertical format. Colours: warm white ground, oat, umber, warm black ink, one rust block. Composition: a single wide vertical dry-brush stroke in umber and ink descending from the upper third to the lower third, slightly off centre to the left, purely abstract and not resembling any letter, character or symbol; a small soft-edged rust rectangle to its lower right; generous empty ground around. Texture: dry-brush streaks with the paper showing through, granulating ink, soft deckled wash edges. Keep key marks off the edges. The artwork alone, flat and frontal, edge to edge: no frame, no wall, no perspective, no text, no signature.","palette":["#B5674A","#ECE7DE","#D3C6B1","#553C2C","#1F1E1C"],"aspect":"2:3","candidates":2,"resolution":"2K"}$job$::jsonb);
insert into photo_jobs (kind, params) values ('edition', $job${"id":"art-ed-dw-ink-3","style":"dark-walnut","prompt":"Abstract ink-wash painting on canvas, vertical format. Colours: warm white, oat, umber, warm black ink, one thin rust band. Composition: five stacked horizontal washes of uneven height, darkest umber and ink at the bottom and fading to almost nothing at the top; the second band from the bottom is a thin rust wash; edges irregular and hand-drawn, not geometric. Texture: wet-in-wet blooms, tide lines between the bands, canvas weave visible. Keep key marks off the edges. The artwork alone, flat and frontal, edge to edge: no frame, no wall, no perspective, no text, no signature.","palette":["#B5674A","#ECE7DE","#D3C6B1","#553C2C","#1F1E1C"],"aspect":"2:3","candidates":2,"resolution":"2K"}$job$::jsonb);
insert into photo_jobs (kind, params) values ('edition', $job${"id":"art-ed-lo-still-shore","style":"light-oak","prompt":"Quiet minimal landscape painting, thin tempera and watercolour on paper mounted on canvas. Colours: rice-paper white, stone linen, moss sage, mushroom taupe. Composition: a very low horizon in the lower third; still water and mist rendered as two pale bands of linen and paper white; a thin, soft sage strip of distant shore; a faint taupe reflection beneath it; a vast empty pale sky above; no trees, no boats, no buildings, no figures. Texture: soft dry washes, visible paper grain, feathered horizon, matte. Keep key marks off the edges. The artwork alone, flat and frontal, edge to edge: no frame, no wall, no perspective, no text, no signature.","palette":["#868A6C","#ECE7DC","#D6CDBE","#A99E8F"],"aspect":"3:2","candidates":2,"resolution":"2K"}$job$::jsonb);
insert into photo_jobs (kind, params) values ('edition', $job${"id":"art-ed-lo-line-1","style":"light-oak","prompt":"Minimal line drawing in charcoal ink on handmade paper mounted on canvas. Colours: rice-paper white ground, stone linen, charcoal line, a pale wash of moss sage. Composition: one continuous, slightly trembling hand-drawn charcoal line travelling from the left edge to the right edge like the contour of a distant ridge, sitting in the lower half; beneath part of it, a single soft translucent sage wash; everything else is empty paper; the line is abstract and forms no letters or symbols. Texture: handmade paper fibres, ink line with natural variation in weight, a soft-edged watercolour wash. One image, hung as two panels: keep the centre band and the edges free of key marks. The artwork alone, flat and frontal, edge to edge: no frame, no wall, no perspective, no text, no signature.","palette":["#868A6C","#ECE7DC","#D6CDBE","#2B2926"],"aspect":"3:2","candidates":2,"resolution":"2K"}$job$::jsonb);
insert into photo_jobs (kind, params) values ('edition', $job${"id":"art-ed-lo-morning-mist","style":"light-oak","prompt":"Soft tonal landscape, watercolour and thin gouache on paper mounted on canvas. Colours: rice-paper white, stone linen, mushroom taupe, a hint of moss sage. Composition: three overlapping low hills dissolving in fog, each a paler band than the one in front; the nearest carries a hint of sage; the upper half is empty mist; no sun, no trees, no buildings. Texture: wet-on-wet gradients, paper grain, very low contrast. Keep key marks off the edges. The artwork alone, flat and frontal, edge to edge: no frame, no wall, no perspective, no text, no signature.","palette":["#868A6C","#ECE7DC","#D6CDBE","#A99E8F"],"aspect":"4:3","candidates":2,"resolution":"2K"}$job$::jsonb);
insert into photo_jobs (kind, params) values ('edition', $job${"id":"art-ed-lo-line-2","style":"light-oak","prompt":"Minimal composition, ink and paper collage on handmade paper mounted on canvas. Colours: rice-paper white, stone linen, charcoal, moss sage. Composition: three thin horizontal hand-drawn charcoal lines of different lengths, stacked with wide gaps in the right half; behind them, a single soft-edged upright rectangle of pale sage torn paper, left of centre; the rest is empty. Texture: layered translucent paper with torn edges, fine ink lines, visible fibres. Keep key marks off the edges. The artwork alone, flat and frontal, edge to edge: no frame, no wall, no perspective, no text, no signature.","palette":["#868A6C","#ECE7DC","#D6CDBE","#2B2926"],"aspect":"4:3","candidates":2,"resolution":"2K"}$job$::jsonb);
insert into photo_jobs (kind, params) values ('edition', $job${"id":"art-ed-lo-winter-light","style":"light-oak","prompt":"Quiet vertical landscape, tempera on paper mounted on canvas. Colours: rice-paper white, stone linen, mushroom taupe, a thin charcoal accent, a trace of moss sage. Composition: a tall pale sky fading from linen at the top to paper white; very low in the picture, a thin dark treeline drawn as one soft uneven charcoal-and-sage band; below it, a strip of snow-pale ground with a faint taupe shadow; nothing else. Texture: chalky matte tempera, soft gradients, paper grain. Keep key marks off the edges. The artwork alone, flat and frontal, edge to edge: no frame, no wall, no perspective, no text, no signature.","palette":["#868A6C","#ECE7DC","#D6CDBE","#A99E8F","#2B2926"],"aspect":"2:3","candidates":2,"resolution":"2K"}$job$::jsonb);
insert into photo_jobs (kind, params) values ('edition', $job${"id":"art-ed-lo-line-3","style":"light-oak","prompt":"Minimal vertical ink drawing on handmade paper mounted on canvas. Colours: rice-paper white, stone linen, charcoal, moss sage. Composition: a single slender vertical brushed charcoal line, slightly curved like a grass stem, rising from the lower edge to two thirds of the height, right of centre; one small soft sage disc floating to its upper left; all else empty; abstract, no letters or symbols. Texture: dry-brush line with broken edges, soft watercolour disc, paper fibres. Keep key marks off the edges. The artwork alone, flat and frontal, edge to edge: no frame, no wall, no perspective, no text, no signature.","palette":["#868A6C","#ECE7DC","#D6CDBE","#2B2926"],"aspect":"2:3","candidates":2,"resolution":"2K"}$job$::jsonb);
insert into photo_jobs (kind, params) values ('edition', $job${"id":"art-ed-gl-travertine-1","style":"greige-luxe","prompt":"Tonal abstract relief painting, plaster and marble dust on canvas. Colours: ivory, greige, travertine, one hairline of champagne. Composition: three broad horizontal trowelled fields of slightly different tone, ivory at the top, greige in the middle, travertine at the base, their boundaries soft and uneven; one thin horizontal champagne seam between the upper two fields, covering under 3 % of the surface. Texture: thick matte plaster with long palette-knife drags, small pits and ridges like cut travertine, raking-light relief kept subtle. Keep key marks off the edges. The artwork alone, flat and frontal, edge to edge: no frame, no wall, no perspective, no text, no signature.","palette":["#B8A27A","#EDE6DA","#CFC4B4","#D7C8AF"],"aspect":"3:2","candidates":2,"resolution":"2K"}$job$::jsonb);
insert into photo_jobs (kind, params) values ('edition', $job${"id":"art-ed-gl-champagne-field","style":"greige-luxe","prompt":"Large tonal field painting, plaster and mineral pigment on canvas. Colours: ivory, greige, a mocha undertone, a fine champagne line. Composition: a wide, almost empty ivory field; in the lower third a warm mocha undertone shows through the plaster like a shadow under a veil, strongest at the lower left; a single fine champagne line runs diagonally across the upper right, covering under 3 % of the surface. Texture: layered plaster skim coats scraped back, soft ridges, matte with a faint mineral sheen only on the champagne line. Keep key marks off the edges. The artwork alone, flat and frontal, edge to edge: no frame, no wall, no perspective, no text, no signature.","palette":["#B8A27A","#EDE6DA","#CFC4B4","#8B6F5E"],"aspect":"3:2","candidates":2,"resolution":"2K"}$job$::jsonb);
insert into photo_jobs (kind, params) values ('edition', $job${"id":"art-ed-gl-hush","style":"greige-luxe","prompt":"Near-monochrome relief painting, plaster on canvas. Colours: ivory, a shadow tone of greige, a trace of champagne. Composition: one wide, shallow arc ridge sweeping from the lower left to the upper right like a dune crest; the form is read only by its soft shadow; a faint champagne warmth along the crest; otherwise a calm ivory field. Texture: smooth trowelled plaster with one raised ridge, fine sanded grain, matte. Keep key marks off the edges. The artwork alone, flat and frontal, edge to edge: no frame, no wall, no perspective, no text, no signature.","palette":["#B8A27A","#EDE6DA","#CFC4B4"],"aspect":"4:3","candidates":2,"resolution":"2K"}$job$::jsonb);
insert into photo_jobs (kind, params) values ('edition', $job${"id":"art-ed-gl-stone-light","style":"greige-luxe","prompt":"Tonal abstract, plaster and limewash on canvas. Colours: ivory, greige, warm taupe, a hairline of champagne. Composition: two large planes meeting on a soft shallow diagonal: a lit ivory plane above, a greige plane below, with a narrow warm taupe shadow where they meet; one hairline of champagne along the meeting edge. Texture: chalky limewash layers, soft brushed clouds, slight plaster relief at the diagonal. Keep key marks off the edges. The artwork alone, flat and frontal, edge to edge: no frame, no wall, no perspective, no text, no signature.","palette":["#B8A27A","#EDE6DA","#CFC4B4","#A69686"],"aspect":"4:3","candidates":2,"resolution":"2K"}$job$::jsonb);
insert into photo_jobs (kind, params) values ('edition', $job${"id":"art-ed-gl-mocha-2","style":"greige-luxe","prompt":"Vertical tonal relief painting, plaster and mineral pigment on canvas. Colours: ivory, greige, mocha, a thin champagne line. Composition: a mocha field fills the lower third and rises unevenly into greige and then ivory, like damp plaster drying upward; the upper two thirds stay light; one short horizontal champagne line sits where mocha turns to greige. Texture: dragged plaster with vertical pulls, soft mineral bloom at the transitions, matte. Keep key marks off the edges. The artwork alone, flat and frontal, edge to edge: no frame, no wall, no perspective, no text, no signature.","palette":["#8B6F5E","#EDE6DA","#CFC4B4","#B8A27A"],"aspect":"2:3","candidates":2,"resolution":"2K"}$job$::jsonb);
insert into photo_jobs (kind, params) values ('edition', $job${"id":"art-ed-gl-layers","style":"greige-luxe","prompt":"Vertical abstract relief, layered plaster on canvas. Colours: ivory, travertine, warm taupe, one stratum of champagne. Composition: seven stacked horizontal strata of uneven thickness like a cut block of sedimentary stone, alternating ivory, travertine and taupe; one thin stratum near the middle is champagne; edges hand-made and irregular, not geometric. Texture: trowelled plaster layers with pitted travertine-like pores, soft chipped edges between strata. Keep key marks off the edges. The artwork alone, flat and frontal, edge to edge: no frame, no wall, no perspective, no text, no signature.","palette":["#B8A27A","#EDE6DA","#D7C8AF","#A69686"],"aspect":"2:3","candidates":2,"resolution":"2K"}$job$::jsonb);
insert into photo_jobs (kind, params) values ('edition', $job${"id":"art-ed-med-noon-coast","style":"mediterranean","prompt":"Sun-washed coastal study, gouache and dry pigment on paper mounted on canvas. Colours: limewash white, sand, sun-baked terracotta, a strip of sea blue. Composition: a simplified coastline seen from above the shore: a wide limewash-white sky over a narrow horizontal strip of sea blue; below it, soft sand bands; two rounded terracotta headland shapes entering from the left and the right; flat, calm shapes with dry-brushed edges; an imagined place, no boats, no buildings, no people. Texture: chalky gouache, dry-brush edges, paper grain, sun-bleached matte. One image, hung as two panels: keep the centre band and the edges free of key marks. The artwork alone, flat and frontal, edge to edge: no frame, no wall, no perspective, no text, no signature.","palette":["#C2704D","#F3EFE6","#DCCFB8","#2F5673"],"aspect":"3:2","candidates":2,"resolution":"2K"}$job$::jsonb);
insert into photo_jobs (kind, params) values ('edition', $job${"id":"art-ed-med-terracotta-roofs","style":"mediterranean","prompt":"Architecture study, gouache and tempera on paper mounted on canvas. Colours: limewash white, sand, sun-baked terracotta, a thin band of sea blue. Composition: a cluster of simple whitewashed cubic walls and low terracotta roof planes reduced to flat overlapping geometric shapes, stepping down from the upper left to the lower right; sand-coloured shadows; a thin band of sea blue along the top right; an imagined village, not a real place; no windows with detail, no people, no domes. Texture: matte tempera, slightly uneven hand-painted edges, chalk texture. Keep key marks off the edges. The artwork alone, flat and frontal, edge to edge: no frame, no wall, no perspective, no text, no signature.","palette":["#C2704D","#F3EFE6","#DCCFB8","#2F5673"],"aspect":"3:2","candidates":2,"resolution":"2K"}$job$::jsonb);
insert into photo_jobs (kind, params) values ('edition', $job${"id":"art-ed-med-olive-grove","style":"mediterranean","prompt":"Quiet landscape study, gouache on paper mounted on canvas. Colours: limewash white, sand, limestone, olive. Composition: five soft rounded olive-tree canopies of different sizes in a loose row across the middle, each a single flat olive shape with a paler dry-brushed top; a sand ground with long pale limestone shadows; a high empty limewash sky filling the upper half; no trunks drawn in detail, no people, no buildings. Texture: chalky gouache, dry-brush highlights, paper grain. Keep key marks off the edges. The artwork alone, flat and frontal, edge to edge: no frame, no wall, no perspective, no text, no signature.","palette":["#76764B","#F3EFE6","#DCCFB8","#D9C7A8"],"aspect":"4:3","candidates":2,"resolution":"2K"}$job$::jsonb);
insert into photo_jobs (kind, params) values ('edition', $job${"id":"art-ed-med-quiet-cove","style":"mediterranean","prompt":"Coastal study, gouache and watercolour on paper mounted on canvas. Colours: limewash white, sand, sea blue, a little sun-baked terracotta. Composition: a single calm crescent of sea blue held inside a wide curve of sand, seen from above; one small terracotta rock form at the right end of the crescent; a broad limewash-white margin above; flat shapes with soft edges; no boats, no people, no umbrellas. Texture: watercolour blooms inside the blue, chalky gouache sand, visible paper. Keep key marks off the edges. The artwork alone, flat and frontal, edge to edge: no frame, no wall, no perspective, no text, no signature.","palette":["#C2704D","#F3EFE6","#DCCFB8","#2F5673"],"aspect":"4:3","candidates":2,"resolution":"2K"}$job$::jsonb);
insert into photo_jobs (kind, params) values ('edition', $job${"id":"art-ed-med-arch-shade","style":"mediterranean","prompt":"Vertical architecture study, gouache and limewash on paper mounted on canvas. Colours: limewash white, sand, limestone, sun-baked terracotta. Composition: one tall whitewashed arched opening, slightly right of centre, with a deep flat terracotta shadow inside it; a diagonal band of sand-coloured light across the wall and the ground; two limestone steps at the base; an imagined building, no door detail, no plants, no people. Texture: chalky limewash layers, soft hand-painted edges, fine plaster grain. Keep key marks off the edges. The artwork alone, flat and frontal, edge to edge: no frame, no wall, no perspective, no text, no signature.","palette":["#C2704D","#F3EFE6","#DCCFB8","#D9C7A8"],"aspect":"2:3","candidates":2,"resolution":"2K"}$job$::jsonb);
insert into photo_jobs (kind, params) values ('edition', $job${"id":"art-ed-med-steps-sea","style":"mediterranean","prompt":"Vertical architecture study, gouache on paper mounted on canvas. Colours: limewash white, sand, sun-baked terracotta, a sliver of sea blue. Composition: a flight of broad whitewashed steps climbing between two plain white walls, drawn as flat stacked shapes with sand-coloured shadows; one simple terracotta pot shape on a step at the lower left; at the very top, a narrow sliver of sea blue; an imagined place, no railings, no people, no text on walls. Texture: matte gouache, slightly uneven edges, chalk texture. Keep key marks off the edges. The artwork alone, flat and frontal, edge to edge: no frame, no wall, no perspective, no text, no signature.","palette":["#C2704D","#F3EFE6","#DCCFB8","#2F5673"],"aspect":"2:3","candidates":2,"resolution":"2K"}$job$::jsonb);
